// The question-bank barrel.
//
// ############################################################################
// #  FROZEN. Do not edit this file when adding questions.                    #
// #  Content work only ever edits the array inside a single topic file.      #
// #  That guarantees no authoring step can break the build.                  #
// ############################################################################
//
// Explicit imports, not import.meta.glob: glob resolves differently under
// vitest than under vite, and it silently hides a file that failed to match.

import topics from '../topics.js'
import { validateBank } from '../../lib/validateBank.js'

import syntaxBasics from './syntax-basics.js'
import datatypesNumbers from './datatypes-numbers.js'
import listsTuples from './lists-tuples.js'
import dictsSets from './dicts-sets.js'
import controlFlow from './control-flow.js'
import functions from './functions.js'
import comprehensions from './comprehensions.js'
import oop from './oop.js'
import oopAdvanced from './oop-advanced.js'
import errorsExceptions from './errors-exceptions.js'
import modulesPackaging from './modules-packaging.js'
import filesIo from './files-io.js'
import stdlib from './stdlib.js'
import decoratorsClosures from './decorators-closures.js'
import iteratorsProtocols from './iterators-protocols.js'
import concurrencyAsync from './concurrency-async.js'
import testingQuality from './testing-quality.js'
import performanceMemory from './performance-memory.js'
import numpy from './numpy.js'
import pandas from './pandas.js'
import vizMatplotlib from './viz-matplotlib.js'
import featureEngineering from './feature-engineering.js'
import sklearnCore from './sklearn-core.js'
import modelEvaluation from './model-evaluation.js'
import neuralNets from './neural-nets.js'
import pytorch from './pytorch.js'
import tensorflowKeras from './tensorflow-keras.js'
import llmsTransformers from './llms-transformers.js'
import mlopsDeploy from './mlops-deploy.js'

/** Every authored question, in topic order. */
export const allQuestions = [
  ...syntaxBasics,
  ...datatypesNumbers,
  ...listsTuples,
  ...dictsSets,
  ...controlFlow,
  ...functions,
  ...comprehensions,
  ...oop,
  ...oopAdvanced,
  ...errorsExceptions,
  ...modulesPackaging,
  ...filesIo,
  ...stdlib,
  ...decoratorsClosures,
  ...iteratorsProtocols,
  ...concurrencyAsync,
  ...testingQuality,
  ...performanceMemory,
  ...numpy,
  ...pandas,
  ...vizMatplotlib,
  ...featureEngineering,
  ...sklearnCore,
  ...modelEvaluation,
  ...neuralNets,
  ...pytorch,
  ...tensorflowKeras,
  ...llmsTransformers,
  ...mlopsDeploy,
]

let cached = null

/**
 * The app's single entry point to question data.
 *
 * Returns `{ questions, errors, warnings }`.
 *
 * In development the caller shows `errors` in a loud red banner so a malformed
 * question is impossible to miss. In production the invalid questions are
 * filtered out and the app carries on -- one bad question must never take the
 * whole app down.
 */
export function getBank() {
  if (cached) return cached

  const { errors, warnings } = validateBank(allQuestions, topics)
  const isDev = typeof import.meta !== 'undefined' && import.meta.env && import.meta.env.DEV

  let questions = allQuestions
  if (errors.length > 0) {
    const badIds = new Set(errors.map((e) => e.id))
    questions = allQuestions.filter((q) => !badIds.has(q && q.id))
    if (isDev) {
      console.error(`[question bank] ${errors.length} invalid question(s):`)
      errors.slice(0, 20).forEach((e) => console.error(`  ${e.id ?? `#${e.index}`}: ${e.message}`))
    } else {
      console.warn(`[question bank] dropped ${errors.length} invalid question(s)`)
    }
  }

  cached = { questions, errors, warnings }
  return cached
}

export default getBank
